function VotesGeoBar({ selectedProvinces, setSelectedProvinces, selectedDistricts, setSelectedDistricts, selectedLgus, setSelectedLgus, searchQuery, setSearchQuery }) {
  const [openDropdown, setOpenDropdown] = C.useState(null); // 'provinces' | 'districts' | 'lgus' | null

  // Available districts based on selected provinces
  const availableDistricts = C.useMemo(() => {
    return VOTES_PROVINCES
      .filter(p => selectedProvinces.includes(p.id))
      .flatMap(p => p.districts.map(d => ({ ...d, provinceName: p.name, provinceId: p.id })));
  }, [selectedProvinces]);

  // Available LGUs based on selected provinces & districts
  const availableLgus = C.useMemo(() => {
    return availableDistricts
      .filter(d => selectedDistricts.length === 0 || selectedDistricts.includes(d.id))
      .flatMap(d => d.lgus.map(lgu => ({ name: lgu, districtId: d.id, districtName: d.name, provinceName: d.provinceName })));
  }, [availableDistricts, selectedDistricts]);

  const toggleProvince = (id) => {
    setSelectedProvinces(prev => {
      const next = prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id];
      return next.length === 0 ? ['camsur', 'mindoro'] : next;
    });
  };

  const toggleDistrict = (id) => {
    setSelectedDistricts(prev => {
      return prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id];
    });
  };

  const toggleLgu = (lguName) => {
    setSelectedLgus(prev => {
      return prev.includes(lguName) ? prev.filter(x => x !== lguName) : [...prev, lguName];
    });
  };

  const selectAll = () => {
    setSelectedProvinces(['camsur', 'mindoro']);
    setSelectedDistricts([]);
    setSelectedLgus([]);
    setSearchQuery('');
  };

  const selectCamSurOnly = () => {
    setSelectedProvinces(['camsur']);
    setSelectedDistricts([]);
    setSelectedLgus([]);
  };

  const selectMindoroOnly = () => {
    setSelectedProvinces(['mindoro']);
    setSelectedDistricts([]);
    setSelectedLgus([]);
  };

  const filteredLgus = searchQuery.trim()
    ? availableLgus.filter(item => item.name.toLowerCase().includes(searchQuery.toLowerCase()))
    : availableLgus;

  return o.jsxs('div', { className: 'bg-white border-b border-slate-200 px-4 sm:px-6 py-3 space-y-2.5 shadow-sm sticky top-[57px] z-10', children: [
    o.jsxs('div', { className: 'flex flex-wrap items-center justify-between gap-2.5', children: [
      // Left: Quick preset pills & province selector
      o.jsxs('div', { className: 'flex flex-wrap items-center gap-1.5 sm:gap-2', children: [
        o.jsxs('div', { className: 'flex items-center gap-1.5 text-xs font-bold text-slate-700 bg-slate-100 px-2.5 py-1.5 rounded-lg border border-slate-200', children: [
          o.jsx(Gn, { size: 14, className: 'text-blue-600' }),
          'Geographic Scope:'
        ]}),
        
        // Province Multi-Select Buttons
        VOTES_PROVINCES.map(p => {
          const active = selectedProvinces.includes(p.id);
          return o.jsxs('button', {
            key: p.id,
            onClick: () => toggleProvince(p.id),
            className: `flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border ${active ? 'bg-blue-600 text-white border-blue-600 shadow-sm' : 'bg-slate-50 text-slate-600 border-slate-200 hover:bg-slate-100'}`,
            children: [
              o.jsx('span', { className: `w-1.5 h-1.5 rounded-full ${active ? 'bg-white' : 'bg-slate-400'}` }),
              p.name,
              o.jsx('span', { className: `text-[10px] px-1.5 py-0.2 rounded-full ${active ? 'bg-blue-700 text-blue-100' : 'bg-slate-200 text-slate-600'}`, children: p.totalLgus + ' LGUs' })
            ]
          });
        }),

        o.jsx('button', {
          onClick: selectAll,
          className: `px-2.5 py-1.5 rounded-lg text-xs font-medium border transition ${selectedProvinces.length === 2 && selectedDistricts.length === 0 && selectedLgus.length === 0 ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`,
          children: 'All 52 LGUs'
        })
      ]}),

      // Right: Active summary pill
      o.jsxs('div', { className: 'flex items-center gap-2 text-xs text-slate-500', children: [
        o.jsx('span', { className: 'font-medium text-slate-700', children: (selectedLgus.length > 0 ? `${selectedLgus.length} specific LGUs` : selectedDistricts.length > 0 ? `${selectedDistricts.length} Districts filtered` : `${availableLgus.length} LGUs active`) }),
        (selectedDistricts.length > 0 || selectedLgus.length > 0) && o.jsx('button', {
          onClick: () => { setSelectedDistricts([]); setSelectedLgus([]); },
          className: 'text-blue-600 hover:text-blue-800 font-semibold underline text-xs ml-1',
          children: 'Reset filters'
        })
      ]})
    ]}),

    // Second Row: District & LGU Multi-Select controls
    o.jsxs('div', { className: 'flex flex-wrap items-center gap-2 pt-1 border-t border-slate-100', children: [
      // District Pills Multi-Select
      o.jsx('div', { className: 'text-[11px] font-semibold text-slate-500 uppercase tracking-wider shrink-0', children: 'Districts:' }),
      o.jsxs('div', { className: 'flex flex-wrap items-center gap-1.5 flex-1', children: [
        availableDistricts.map(d => {
          const active = selectedDistricts.includes(d.id);
          return o.jsxs('button', {
            key: d.id,
            onClick: () => toggleDistrict(d.id),
            className: `px-2.5 py-1 rounded-md text-[11px] font-medium border transition ${active ? 'bg-blue-100 text-blue-800 border-blue-300 font-semibold' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'}`,
            children: [
              d.provinceId === 'camsur' ? 'CamSur ' : 'Mindoro ',
              d.name.split(' (')[0]
            ]
          });
        })
      ]}),

      // City/Municipality quick search
      o.jsxs('div', { className: 'relative flex items-center shrink-0 w-full sm:w-56', children: [
        o.jsx('input', {
          type: 'text',
          value: searchQuery,
          onChange: e => setSearchQuery(e.target.value),
          placeholder: 'Search 52 municipalities…',
          className: 'w-full pl-7 pr-3 py-1 text-xs rounded-md border border-slate-200 bg-slate-50 focus:bg-white focus:outline-none focus:ring-1 focus:ring-blue-500'
        }),
        o.jsx($N, { size: 12, className: 'absolute left-2 text-slate-400' }),
        searchQuery && o.jsx('button', { onClick: () => setSearchQuery(''), className: 'absolute right-2 text-slate-400 hover:text-slate-600 text-xs', children: '×' })
      ]})
    ]})
  ]});
}

